mapper.select:
select distinct m.menu_id, m.parent_id, m.menu_name, m.menu_name_i18n_key, m.path, m.component, m.`query`, m.visible, m.status, ifnull(m.perms, '') as perms, m.is_frame, m.is_cache, m.menu_type, m.icon, m.order_num from sys_menu m left join sys_role_menu rm on m.menu_id = rm.menu_id left join (SELECT 'system' as src, NULL AS src_id, user_id, role_id FROM sys_user_role
UNION SELECT 'team' as src, ut.team_id as src_id, ut.user_id, utr.role_id FROM sys_user_team_role utr LEFT JOIN sys_user_team ut ON ut.user_team_id = utr.user_team_id AND ut.team_id = #{teamId}
UNION SELECT 'project' as src, up.project_id as src_id, up.user_id, upr.role_id FROM sys_user_project_role upr LEFT JOIN sys_user_project up ON up.user_project_id = upr.user_project_id AND up.project_id = #{projectId} ) ur on rm.role_id = ur.role_id left join sys_role ro on ur.role_id = ro.role_id left join sys_user u on ur.user_id = u.user_id where u.user_id = #{userId} and m.menu_type in ('M', 'C') and m.status = 0 AND ro.status = 0 order by m.parent_id, m.order_num



    status = 0

        AND menu_name like concat('%', #{menuName}, '%')


        AND visible = #{visible}


        AND status = #{status}


order by parent_id, order_num

select distinct m.menu_id, m.parent_id, m.menu_name, m.menu_name_i18n_key, m.path, m.component, m.`query`, m.visible, m.status, ifnull(m.perms, '') as perms, m.is_frame, m.is_cache, m.menu_type, m.icon, m.order_num from sys_menu m left join sys_role_menu rm on m.menu_id = rm.menu_id left join sys_user_role ur on rm.role_id = ur.role_id left join sys_role ro on ur.role_id = ro.role_id where ur.user_id = #{params.userId}
AND m.menu_name like concat('%', #{menuName}, '%')
AND m.visible = #{visible}
AND m.status = #{status}
order by m.parent_id, m.order_num

select m.menu_id
from sys_menu m
         left join sys_role_menu rm on m.menu_id = rm.menu_id
where rm.role_id = #{roleId}

    and m.menu_id not in (
        select m.parent_id
        from sys_menu m
                 inner join sys_role_menu rm on m.menu_id = rm.menu_id and rm.role_id = #{roleId}
    )

order by m.parent_id, m.order_num

mapper.update:
update sys_menu
menu_name = #{menuName}, menu_name_i18n_key = #{menuNameI18nKey}, parent_id = #{parentId}, order_num = #{orderNum}, path = #{path}, component = #{component}, `query` = #{query}, is_frame = #{isFrame}, is_cache = #{isCache}, menu_type = #{menuType}, visible = #{visible}, status = #{status}, perms = #{perms}, icon = #{icon}, update_by = #{updateBy}, update_time = NOW()
where menu_id = #{menuId}
